+#!/usr/bin/env node
+import { spawn } from "node:child_process";
+import { createHash, randomUUID } from "node:crypto";
+import { existsSync, unwatchFile, watchFile } from "node:fs";
+import { open, rename, unlink } from "node:fs/promises";
