+        temporary.add(staging);
+        let failure;
+        try {
+          await handle.writeFile(text);
+        } catch (error) {
+          failure = error;
+        }
+        try {
+          await handle.close();
+        } catch (error) {
+          failure ??= error;
+        }
+        if (failure) throw failure;
+        await rename(staging, file);
+        stagingFiles.delete(staging);
+        temporary.delete(staging);
+        temporary.add(file);
+        if (file !== rootFile) {
+          materialized.add(file);
+          created.push(file);
+        }
+      }
